def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = op.count('C')
    op_d = n - op_c
    my_d = n - my.count('C')

    resp_c = 0
    resp_d = 0
    for i in range(1, n):
        if my[i - 1] == 'D':
            if op[i] == 'C':
                resp_c += 1
            else:
                resp_d += 1

    start = n - 10
    if start < 0:
        start = 0
    rec_d = 0
    for i in range(start, n):
        if op[i] == 'D':
            rec_d += 1

    last_my = my[-1]
    last_op = op[-1]

    run_d = 0
    attempts = 0
    if last_op == 'D':
        i = n - 1
        while i >= 0 and op[i] == 'D':
            run_d += 1
            if my[i] == 'C':
                attempts += 1
            i -= 1

    run_c = 0
    if last_op == 'C':
        i = n - 1
        while i >= 0 and op[i] == 'C':
            run_c += 1
            i -= 1

    pending_cap = max(6, n // 10)
    exploit_cap = max(8, n // 10)
    post_cap = max(8, n // 8)

    if op_c == 0:
        return 'D'

    if n >= 25 and op_d * 5 >= n * 3:
        return 'D'

    if rec_d >= 9 and n >= 12:
        return 'D'

    if last_op == 'D':
        if attempts >= 4:
            return 'D'

        if run_d == 1:
            if op_c * 4 >= n * 3:
                return 'C'
            return 'D'

        if run_d == 2:
            return 'D'

        if attempts >= 2 and op_d * 10 >= n * 3:
            return 'D'

        if op_c > op_d:
            return 'C'

        if op_c * 5 >= n * 2 and attempts <= 2:
            return 'C'

        return 'D'

    if last_my == 'D':
        if resp_c >= 1 and op_c * 4 >= n * 3 and op_d <= pending_cap:
            return 'D'
        if op_c * 4 >= n * 3 and my_d <= 2:
            return 'C'
        if op_c * 5 >= n * 2:
            return 'C'
        return 'D'

    if n >= 2 and my[-2] == 'D' and op[-2] == 'C':
        if op_c * 4 >= n * 3 and op_d <= exploit_cap:
            return 'D'

    if resp_c >= 2 and resp_c > resp_d:
        if op_c * 4 >= n * 3 and op_d <= exploit_cap and run_c >= 2:
            return 'D'

    if my_d <= 2 and 3 <= op_d <= post_cap:
        if run_c >= 6 and op_c * 4 >= n * 3 and resp_c <= 2:
            return 'D'

    if op_d * 2 > n:
        return 'D'

    return 'C'
